  function cashOf(p){ var v=null; try{ v=(window.KV_SEAT&&window.KV_SEAT(p,"cash")); }catch(e){} var ff=(window.KV_FLAGS&&window.KV_FLAGS())||{}; if(v==null) v=ff["cash"+p]; if(v==null) v=ff["cash_p"+p]; if(v==null) v=ff["p"+p+"_cash"]; if(v==null){ var ds=document.body.querySelectorAll("div"); for(var i=0;i<ds.length;i++){ var tx=ds[i].textContent||""; if(tx.length<400 && tx.indexOf("P"+p)>=0 && /CASH\s+(\d+)/.test(tx) && ds[i].children.length<12){ v=+RegExp.$1; break; } } } return v==null?0:Math.round(v); }
  function dialogOpen(){ return !!document.querySelector("[data-kvmodal]"); }
  setInterval(function(){
    var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
    if(!(f.t0>0)){ why("game not started (t0="+f.t0+")"); return; } if(f.over || window.KV_SEALED) return;
    if((f.left||0)<25){ why("under 25s left"); return; }
    if(Date.now()-last<55000){ why("waiting out spacing "+Math.round((55000-(Date.now()-last))/1000)+"s"); return; }
    if(dialogOpen()){ why("a dialog is open"); return; }
    // __KV_V269: in a relay game, offers only during our own turn with an empty apply queue
    var __mpO=window.KV_MP2;
    if(__mpO && __mpO.room && __mpO.started){
      if((__mpO.queue||[]).length){ why("remote moves pending"); return; }
      if((f.seat||1)!==__mpO.seat){ why("not our turn"); return; }
    }
    var humans=window.KV_HUMANS||[1]; if(!humans.length) return;
    var human=humans[Math.floor(Math.random()*humans.length)];
    var N=window.KV_NAMES||{};
    var mine=Object.keys(N).map(function(k){return parseInt(k,10);}).filter(function(t){ return window.KV_OWNER&&window.KV_OWNER(t)===human && !(f["ls_t"+t]>0); });
    if(!mine.length){ why("you own no unlisted block yet"); return; }
    // __KV_V205: in a relay game only seats this client owns may be driven by local AI
    var __mp=window.KV_MP2, __relay=!!(__mp&&__mp.room&&__mp.started);
    var bots=[1,2,3,4].filter(function(p){ return humans.indexOf(p)<0 && cashOf(p)>=350 && (!__relay || __mp.owns(p)); }); if(!bots.length){ if(window.KV_LOG && Date.now()-last>60000){ last=Date.now()-25000; why("no bot has 350+ cash P2 "+cashOf(2)+" P3 "+cashOf(3)+" P4 "+cashOf(4)); } return; }
    if(!bots.length) return;
    var bot=bots[Math.floor(Math.random()*bots.length)];
    var tile=mine[Math.floor(Math.random()*mine.length)];
    if(window.KV_NO_BACK && window.KV_NO_BACK(tile,bot)){ tried[bot+":"+tile]=Date.now(); why("P"+bot+" just sold tile "+tile+" \u2014 not buying it back"); return; }
    if(tried[bot+":"+tile] && Date.now()-tried[bot+":"+tile]<150000){ why("P"+bot+" already asked about that block recently"); return; }
    var intr=window.KV_INTRINSIC?window.KV_INTRINSIC(tile):(window.KV_MARKET?window.KV_MARKET(tile):(N[tile].p||100));
    var label=((window.KV_PROFNAME&&window.KV_PROFNAME(bot))||"").toLowerCase();
    var mul=label.indexOf("develop")>=0?1.05:(label.indexOf("trader")>=0?0.90:(label.indexOf("miser")>=0?0.80:0.95));
    var dmB=window.KV_DIST_MULT?window.KV_DIST_MULT(tile,bot,human):{buy:1,why:""};
    var reason = dmB.buy>1 ? dmB.why : (label.indexOf("develop")>=0 ? "the developer wants inventory" : (cashOf(bot)>=600 ? "cash burning a hole" : ""));
    if(!reason){ tried[bot+":"+tile]=Date.now(); why("P"+bot+" has no reason to want tile "+tile); return; }
    var amt=Math.round(intr*mul*dmB.buy*(0.95+window.KV_RND("offer_amt",(window.KV_MP2&&window.KV_MP2.head)||0)*0.12)/5)*5;   // __KV_V278
    if(amt<20 || cashOf(bot)-amt<180){ if(window.KV_LOG) why("P"+bot+" eyed tile "+tile+" at "+amt+" but has only "+cashOf(bot)); last=Date.now()-25000; return; }
    // __KV_V230: skip tiles under bid embargo
    try{ var __bb=(window.__KV_BIDBLOCK||{})[tile];
      if(__bb && Date.now()-__bb < 180000){ return; } }catch(e){}
    last=Date.now(); tried[bot+":"+tile]=Date.now();
    var nm=(N[tile]&&N[tile].n)||("block "+tile);
    if(window.KV_LOG) window.KV_LOG("P"+bot+"  offers  "+amt+"  for your "+nm+(label?("  \u00b7 the "+label):"")+"  \u00b7 "+reason, COL[bot]);
    if(window.KV_MOVE) window.KV_MOVE(bot,"bid:"+tile,amt);
    if(window.KV_ASK_HUMAN) window.KV_ASK_HUMAN(tile,bot,human,amt,nm);
  }, 3000);
})();

// ---- narrate bot offer decisions ----
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    var lastAns=null, lastTile=null;
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var t=f.offer_tile, a=f.oans;
      if(t==null||t<0||a==null||a<0){ lastAns=null; return; }
      if(a===lastAns&&t===lastTile) return;
      lastAns=a; lastTile=t;
      var N=window.KV_NAMES||{}, nm=(N[t]&&N[t].n)||("block "+t);
      var o=window.KV_OWNER?window.KV_OWNER(t):null;
      var hz=f["hz_t"+t], rv=f["rv_t"+t]||0;
      var why = a===0
        ? (hz>=34&&!rv ? "hazard too high" : "price beats value")
        : (rv>0 ? "improved, holding" : "building the district");
      if(o) window.KV_LOG("P"+o+"  "+(a===0?"SELLS":"KEEPS")+"  "+nm+"  \u2014 "+why, COL[o]);
    },350);
  })();

  // ================= MARKET COMPS + RENOVATION =================
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    window.KV_COMPS=1.0;
    var recent=[];

    window.KV_MARKET=function(t){
      var N=window.KV_NAMES||{}, d=N[t]; if(!d) return 0;
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var hz=f["hz_t"+t]||0, rv=f["rv_t"+t]||0;
      var age=f["age_t"+t]||0, tax=f["tax_t"+t]||0;
      var q=(f["q_t"+t]==null?1:f["q_t"+t]);
      var factor=Math.max(0.35, 1.32 - hz/120 - age/600 - tax/260);
      return Math.round(d.p * q * factor * window.KV_COMPS * (1+0.12*rv));
    };

    // every ownership change is a comp
    var lastOwner={};
    setInterval(function(){
      var N=window.KV_NAMES||{};
      Object.keys(N).forEach(function(k){
        var t=parseInt(k,10), o=window.KV_OWNER?window.KV_OWNER(t):null;
        if(lastOwner[t]===undefined){ lastOwner[t]=o; return; }
        if(o!==lastOwner[t]){
          if(o){
            var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
            var hz=f["hz_t"+t]||0;
            recent.push(Math.max(0.55, Math.min(1.5, 1 - hz/220 + (lastOwner[t]?0.12:0))));
            while(recent.length>6) recent.shift();
            var s=0; recent.forEach(function(x){s+=x;});
            var prev=window.KV_COMPS;
            window.KV_COMPS=+(s/recent.length).toFixed(3);
            if(window.KV_LOG && Math.abs(window.KV_COMPS-prev)>=0.02){
              window.KV_LOG("market "+(window.KV_COMPS>prev?"up":"down")+"  index "+window.KV_COMPS.toFixed(2),"#caa64c");
            }
          }
          lastOwner[t]=o;
        }
      });
    },400);

    // market index readout
    var mi=document.createElement("div");
    mi.style.cssText="position:fixed;left:-9999px;top:0;z-index:1;width:214px;background:rgba(20,16,12,.92);border:1px solid #5a4a3a;border-radius:4px;padding:3px 8px;font:11px monospace;color:#f4e4c1;box-sizing:border-box;";
    document.body.appendChild(mi);
    setInterval(function(){
      var c=window.KV_COMPS;
      var col=c>1.02?"#9cd87c":(c<0.95?"#ff6a4a":"#f4e4c1");
      mi.innerHTML="<span style='color:#caa64c;font-weight:700'>MARKET</span> "+
        "<span style='float:right;color:"+col+"'>"+c.toFixed(2)+"\u00d7</span>";
    },500);

    // renovate button inside the property popup
    window.KV_RENOVATE=function(t){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var seat=(window.KV_NET&&window.KV_NET.seat)||(window.KV_HUMANS||[1])[0]||1;
      var o=window.KV_OWNER?window.KV_OWNER(t):null;
      if(o!==seat){ if(window.KV_LOG) window.KV_LOG("renovation: not your property","#ff6a4a"); return; }
      if(!window.KV_SETSTATE){ return; }
      window.KV_SETSTATE("renov_by", seat);
      window.KV_SETSTATE("renov_t", 0);
      var okw = window.KV_SETSTATE("renov", t);
      if(!okw){ if(window.KV_LOG) window.KV_LOG("renovation could not be requested","#ff6a4a"); return; }
      if(window.KV_DEAL) window.KV_DEAL(true,"RENOVATING","P"+seat+" \u00b7 "+((window.KV_NAMES[t]&&window.KV_NAMES[t].n)||t));
      var N=window.KV_NAMES||{};
      if(window.KV_LOG) window.KV_LOG("P"+seat+"  renovating  "+(N[t]?N[t].n:t),COL[seat]);
      window.__KV_RENOV = window.__KV_RENOV || {};
var __rk = seat + ":" + t + ":" + Math.floor(Date.now() / 4000);
if (!window.__KV_RENOV[__rk]) { window.__KV_RENOV[__rk] = 1;
  if (window.KV_MOVE) window.KV_MOVE(seat, "renovate", t); }
      if(window.KV_XP){
        var amt=Math.max(1,Math.round(8*(window.KV_XP_MULT==null?1:window.KV_XP_MULT)));
        window.KV_XP[seat]=(window.KV_XP[seat]||0)+amt;
        if(window.KV_LOG) window.KV_LOG("P"+seat+"  +"+amt+" XP  capital improvement",COL[seat]);
      }
    };
  })();

  // ================= PRE-PURCHASE DISCLOSURE =================
  (function(){
    var card=document.createElement("div");
    card.style.cssText="position:fixed;left:50%;top:calc(50% - 40px);transform:translateX(-50%);z-index:64;display:none;background:rgba(20,16,12,.96);border:2px solid #caa64c;border-radius:10px;padding:12px 18px;font:12px/1.7 monospace;color:#f4e4c1;min-width:250px;box-shadow:0 6px 30px rgba(0,0,0,.7);text-align:left;";
    document.body.appendChild(card);

    function fairValue(price, hz, age, tax, q){
      var quality = (q==null?1:q);
      var factor = 1.32 - (hz||0)/120 - (age||0)/600 - (tax||0)/260;
      return Math.round(price * quality * Math.max(0.35, factor));
    }
    window.KV_FAIR=fairValue;

    var shownFor=-1, lastVerdict=null;
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var t=f.buy_tile;
      var live=(f.buy!=null&&f.buy>=0)||(f.phase===2);
      var N=window.KV_NAMES||{};
      if(t==null||t<0||!N[t]||!live){ card.style.display="none"; shownFor=-1; return; }
      if(t===shownFor) return;
      shownFor=t;
      var d=N[t], hz=f["hz_t"+t], age=f["age_t"+t], tax=f["tax_t"+t];
      var q=f["q_t"+t];
      var fair=fairValue(d.p,hz,age,tax,q);
      var margin=fair-d.p;
      var ratio=fair/(d.p||1);
      lastVerdict={tile:t, price:d.p, fair:fair, good:margin>=0};
      window.KV_LAST_OFFER=lastVerdict;
      var col=margin>=0?"#9cd87c":"#ff6a4a";
      card.innerHTML="<div style='color:#f0c860;font-weight:700;letter-spacing:1px;margin-bottom:6px'>"+d.n+"</div>"+
        "ASKING <b>"+d.p+"</b><br>"+
        "AGE <b>"+(age!=null?Math.round(age)+" yrs":"?")+"</b> &nbsp; TAX <b>"+(tax!=null?Math.round(tax):"?")+"</b><br>"+
        "HAZARD <b style='color:"+((hz>=30)?"#ff6a4a":"#9cd87c")+"'>"+(hz!=null?Math.round(hz)+"%":"?")+"</b><br>"+
        "<div style='margin-top:6px;padding-top:6px;border-top:1px solid #3a3228'>"+
        "FAIR VALUE <b style='color:"+col+"'>"+fair+"</b><br>"+
        "<span style='color:"+col+"'>"+(margin>=0?("underpriced by "+margin):("overpriced by "+(-margin)))+"</span>"+
        (ratio>=1.15?"<div style='margin-top:5px;background:#9cd87c;color:#12100e;font-weight:700;text-align:center;border-radius:4px;padding:2px'>STEAL</div>":
         (ratio<=0.82?"<div style='margin-top:5px;background:#ff6a4a;color:#12100e;font-weight:700;text-align:center;border-radius:4px;padding:2px'>OVERPRICED</div>":""))+"</div>";
      card.style.display="block";
    },200);

    // XP for underwriting: buying value, or walking away from a bad block
    var prevOwner={};
    setInterval(function(){
      var N=window.KV_NAMES||{}, v=window.KV_LAST_OFFER;
      if(!v) return;
      var o=window.KV_OWNER?window.KV_OWNER(v.tile):null;
      if(prevOwner[v.tile]===undefined){ prevOwner[v.tile]=o; return; }
      if(o!==prevOwner[v.tile]){
        prevOwner[v.tile]=o;
        var humans=window.KV_HUMANS||[1];
        if(o&&humans.indexOf(o)>=0&&v.good&&window.KV_XP){
          var amt=Math.max(1,Math.round(10*(window.KV_XP_MULT==null?1:window.KV_XP_MULT)));
          window.KV_XP[o]=(window.KV_XP[o]||0)+amt;
          if(window.KV_LOG) window.KV_LOG("P"+o+"  +"+amt+" XP  bought under value","#9cd87c");
        }
        window.KV_LAST_OFFER=null;
      }
    },300);
  })();

  // ---- district bonus announcements ----
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    var seen={};
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      for(var gi=0;gi<12;gi++){
        var v=f["dbon_"+gi];
        if(v&&v>0&&!seen[gi]){
          seen[gi]=v;
          if(window.KV_LOG) window.KV_LOG("P"+v+"  DISTRICT COMPLETE  bonus paid",COL[v]);
        }
      }
    },500);
  })();

  // ================= HOLDINGS: who owns what =================
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    var box=document.createElement("div");
    box.style.cssText="position:fixed;left:-9999px;top:0;z-index:1;width:214px;font:11px/1.45 monospace;color:#f4e4c1;";
    var hd=document.createElement("div");
    hd.style.cssText="background:rgba(20,16,12,.94);border:1px solid #5a4a3a;border-radius:4px 4px 0 0;padding:3px 8px;cursor:pointer;letter-spacing:1px;color:#caa64c;font-weight:700;";
    hd.innerHTML="<span>HOLDINGS</span><span style='float:right'>&#9660;</span>";
    var bd=document.createElement("div");
    bd.style.cssText="background:rgba(20,16,12,.88);border:1px solid #5a4a3a;border-top:0;border-radius:0 0 4px 4px;padding:5px 8px;max-height:250px;overflow:auto;";
    box.appendChild(hd); box.appendChild(bd); document.body.appendChild(box);
    var open=true;
    hd.onclick=function(){ open=!open; bd.style.display=open?"block":"none";
      hd.lastChild.innerHTML=open?"&#9660;":"&#9654;"; };

    setInterval(function(){
      if(!open) return;
      var N=window.KV_NAMES||{};
      var by={1:[],2:[],3:[],4:[]}, free=0;
      Object.keys(N).forEach(function(k){
        var t=parseInt(k,10);
        var o=window.KV_OWNER?window.KV_OWNER(t):null;
        if(o&&by[o]) by[o].push({n:N[k].n,p:(window.KV_MARKET?window.KV_MARKET(t):(N[k].p||0))});
        else free++;
      });
      var h="";
      for(var p=1;p<=4;p++){
        var list=by[p], val=0;
        list.forEach(function(x){ val+=x.p; });
        var mine=(window.KV_HUMANS||[1]).indexOf(p)>=0;
        h+="<div style='margin-bottom:4px'>"+
           "<span style='color:"+COL[p]+"'>&#9632;</span> <b>P"+p+(mine?" (you)":"")+"</b> "+
           "<span style='opacity:.6'>"+list.length+" \u00b7 "+val+"</span>";
        if(list.length){
          h+="<div style='padding-left:11px;opacity:.85'>"+
             list.map(function(x){return x.n;}).join("<br>")+"</div>";
        } else {
          h+="<div style='padding-left:11px;opacity:.4'>none</div>";
        }
        h+="</div>";
      }
      h+="<div style='opacity:.5;border-top:1px solid #3a3228;padding-top:3px'>unowned "+free+"</div>";
      bd.innerHTML=h;
    },600);
  })();

  // ================= "YOU" MARKERS =================
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    var st=document.createElement("style");
    st.textContent="@keyframes kvbob{0%,100%{transform:translate(-50%,-100%) translateY(0)}50%{transform:translate(-50%,-100%) translateY(-9px)}}"+
      "@keyframes kvpulse{0%,100%{box-shadow:0 0 0 0 rgba(255,242,160,.55)}50%{box-shadow:0 0 0 7px rgba(255,242,160,0)}}";
    document.head.appendChild(st);

    var marks={};
    function markerFor(p){
      if(marks[p]) return marks[p];
      var d=document.createElement("div");
      d.style.cssText="position:fixed;z-index:58;pointer-events:none;display:none;animation:kvbob 1.1s ease-in-out infinite;text-align:center;";
      d.innerHTML="<div style='font:900 11px monospace;letter-spacing:1px;color:"+COL[p]+";text-shadow:1px 1px 0 #241c12,0 0 8px rgba(0,0,0,.9);margin-bottom:-3px'>"+(p===1?"YOU":("P"+p))+"</div>"+
        "<div style='width:0;height:0;margin:0 auto;border-left:9px solid transparent;border-right:9px solid transparent;border-top:13px solid "+COL[p]+";filter:drop-shadow(0 2px 3px rgba(0,0,0,.8))'></div>";
      document.body.appendChild(d);
      marks[p]=d;
      return d;
    }

    setInterval(function(){
      if(!window.KV_PROJECT||!window.KV_NODE) return;
      var cv=document.querySelector("canvas"); if(!cv) return;
      var r=cv.getBoundingClientRect(), sx=r.width/cv.width, sy=r.height/cv.height;
      var humans=window.KV_HUMANS||[1];
      for(var p=1;p<=4;p++){
        var d=markerFor(p);
        if(humans.indexOf(p)<0){ d.style.display="none"; continue; }
        var n=window.KV_NODE("token_p"+p);
        if(!n||!n.worldPos){ d.style.display="none"; continue; }
        var q=window.KV_PROJECT(n.worldPos);
        if(!q){ d.style.display="none"; continue; }
        d.style.display="block";
        d.style.left=(r.left+q.x*sx)+"px";
        d.style.top=(r.top+q.y*sy-34)+"px";
      }
    },120);

    // pulse the corner card of whoever is up
    setInterval(function(){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var cur=((f.turn||0)%4)+1;
      for(var p=1;p<=4;p++){
        var c=document.getElementById("kvc"+p);
        var card=c&&c.parentNode&&c.parentNode.parentNode;
        if(!card) continue;
        var mine=(window.KV_HUMANS||[1]).indexOf(p)>=0;
        card.style.borderColor = (p===cur) ? COL[p] : (mine ? "rgba(202,166,76,.55)" : "#5a4a3a");
        card.style.animation = (p===cur) ? "kvpulse 1.4s infinite" : "none";
      }
    },300);
  })();

  // ================= PLAY BY PLAY (standalone) =================
  (function(){
    var COL={1:"#d94f4f",2:"#4f7fd9",3:"#4fd98a",4:"#d9c14f"};
    var wrap=document.createElement("div");
    wrap.style.cssText="position:fixed;right:6px;top:380px;z-index:78;width:236px;display:flex;flex-direction:column-reverse;gap:3px;pointer-events:none;max-height:210px;overflow:hidden;";
    document.body.appendChild(wrap);
    var hdr=document.createElement("div");
    hdr.style.cssText="background:rgba(20,16,12,.94);border:1px solid #5a4a3a;border-radius:4px;padding:3px 9px;font:700 11px monospace;color:#caa64c;letter-spacing:2px;";
    hdr.innerHTML="<span>PLAY BY PLAY</span><span style='float:right'>&#9660;</span>";
    hdr.style.cursor="pointer";
    var pbOpen=true;
    hdr.onclick=function(){ pbOpen=!pbOpen; wrap.style.display=pbOpen?"flex":"none";
      hdr.lastChild.innerHTML=pbOpen?"&#9660;":"&#9654;"; };
    document.body.appendChild(hdr);
    hdr.style.position="fixed"; hdr.style.right="6px"; hdr.style.top="356px"; hdr.style.zIndex=78; hdr.style.width="236px"; hdr.style.boxSizing="border-box";


    window.KV_LOG=function(txt,col){
      var r=document.createElement("div");
      r.style.cssText="background:rgba(20,16,12,.92);border-left:4px solid "+(col||"#8a7a5a")+";padding:3px 8px;border-radius:3px;font:11px/1.35 monospace;color:#f4e4c1;box-shadow:0 1px 6px rgba(0,0,0,.5);transition:opacity 1.6s;";
      r.textContent=txt;
      wrap.appendChild(r);
      while(wrap.children.length>7) wrap.removeChild(wrap.firstChild);
      setTimeout(function(){ r.style.opacity=.5; }, 20000);
    };
    window.KV_LOG("play by play ready","#caa64c");

    // every engine sound becomes a line, so nothing happens silently
    var LABEL={dice:"rolls",buy:"buys a block",rent:"rent paid",tax:"taxed",depot:"payday",
               jail:"detained",bust:"bankrupt",hazard:"hazard hits",storm:"storm damage",
               evict:"tenant evicted",bnb:"converted to short-let",gavel:"court",win:"final bell"};
    var prevHook=window.KV_ON_SOUND;
    window.KV_ON_SOUND=function(id){
      try{ if(prevHook) prevHook(id); }catch(e){}
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      var s=((f.turn||0)%4)+1;
      if(LABEL[id]) window.KV_LOG("P"+s+"  "+LABEL[id], COL[s]);
    };
  })();

  // ================= SELF-TEST =================
  setTimeout(function(){
